defs.public.resolve_issue(p_issue uuid):
CREATE OR REPLACE FUNCTION public.resolve_issue(p_issue uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare canonical uuid:=p_issue;i private.issues;visited uuid[]:='{}';k integer;
begin
  for k in 1..16 loop
    if canonical=any(visited) then raise exception 'ALIAS_CYCLE';end if;visited:=array_append(visited,canonical);
    if not exists(select 1 from private.issue_aliases where alias_id=canonical) then exit;end if;
    select canonical_issue_id into canonical from private.issue_aliases where alias_id=canonical;
  end loop;
  if exists(select 1 from private.issue_aliases where alias_id=canonical) then raise exception 'ALIAS_CHAIN_LIMIT';end if;
  select * into i from private.issues where id=canonical;
  if not found or i.publication_state='DRAFT' then return jsonb_build_object('state','NOT_FOUND','message','현재 제공하지 않는 글');end if;
  return jsonb_build_object('canonical_issue_id',i.id,'state',i.publication_state,'message',case i.publication_state when 'PUBLISHED' then '공개된 글' when 'CORRECTION_PENDING' then '내용 확인 중 · 기존 내용 제공 중지' when 'WITHDRAWN' then '근거 확인 불가로 게시 중단' else '현재 제공하지 않는 글' end);
end$function$

defs.public.m1_public_article(p_issue uuid):
CREATE OR REPLACE FUNCTION public.m1_public_article(p_issue uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb;canonical uuid;
begin
  r:=public.resolve_issue(p_issue);if r->>'state'<>'PUBLISHED' then return r;end if;
  canonical:=(r->>'canonical_issue_id')::uuid;
  if not exists(select 1 from private.issues i join private.article_versions v on v.id=i.current_version_id where i.id=canonical and v.public_body->>'_contract'='M1') then return jsonb_build_object('state','NOT_FOUND','message','현재 제공하지 않는 글');end if;
  if not private.m1_current_evidence(canonical) then return jsonb_build_object('state','CORRECTION_PENDING','message','근거·분류 재확인 중 · 기존 내용 제공 중지');end if;
  return public.get_public_article(canonical);
end$function$

