 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o private.outbox;r jsonb;result jsonb:='[]';
begin perform private.assert_server();perform private.assert_initialized();
