defs.public.m0_enqueue(p_effect_key text, p_p:
CREATE OR REPLACE FUNCTION public.m0_enqueue(p_effect_key text, p_payload jsonb DEFAULT '{}'::jsonb, p_environment text DEFAULT 'preview'::text, p_schema_version integer DEFAULT 1, p_kind text DEFAULT 'MOCK_EFFECT'::text)
 RETURNS jsonb
